import{_ as t,C as a,o as i,c as r,E as s,a2 as n}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Escalation Risk Does Not Choose the Protocol","description":"","frontmatter":{"title":"Escalation Risk Does Not Choose the Protocol","date":"2026-09-06","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当数字员工看起来可能失败时，受治理的运行系统在从“当前路径有风险”转向“现在按此成本使用这个协作协议”之前，必须分别知道什么？","summary":"A controlled study shows that detecting likely baseline failure is much easier than predicting which collaboration protocol adds value. Governed escalation should separate failure risk, protocol value, and budget admission.","sources":["research/analysis/Q-20260906-01-escalation-admission-protocol-value-budget.md"],"item_id":"Q-20260906-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-06-risk-does-not-choose-protocol-editorial-v3.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-09-06-risk-does-not-choose-protocol.md","filePath":"en/digital-employee/2026-09-06-risk-does-not-choose-protocol.md","lastUpdated":1788755595000}'),l={name:"en/digital-employee/2026-09-06-risk-does-not-choose-protocol.md"};function c(d,e,h,p,u,m){const o=a("ArticleCover");return i(),r("div",null,[s(o,{image:"/assets/covers/daily-2026-09-06-risk-does-not-choose-protocol-editorial-v3.webp",kicker:"Digital Employee · Daily Research",title:"Escalation Risk Does Not Choose the Protocol",summary:"A controlled study shows that detecting likely baseline failure is much easier than predicting which collaboration protocol adds value. Governed escalation should separate failure risk, protocol value, and budget admission.",version:"Q-20260906-01",status:"Daily Runtime V5 · 2026-09-06",languageHref:"/zh/digital-employee/2026-09-06-risk-does-not-choose-protocol",languageLabel:"中文"}),e[0]||(e[0]=n('<h1 id="escalation-risk-does-not-choose-the-protocol" tabindex="-1">Escalation Risk Does Not Choose the Protocol <a class="header-anchor" href="#escalation-risk-does-not-choose-the-protocol" aria-label="Permalink to &quot;Escalation Risk Does Not Choose the Protocol&quot;">​</a></h1><p>A digital employee concludes that its current answer is likely wrong and immediately broadcasts the task to more agents. The risk assessment may be correct while the escalation is still poorly governed: the expensive collaboration pattern may add less value than a cheaper alternative, and nobody may have authorized the extra cost.</p><p>The core proposition is: <strong>failure-risk admission, protocol-specific value, and budget admission are separate evidence decisions. Detecting likely failure does not select a collaboration topology, and selecting a topology does not authorize its cost.</strong></p><h2 id="one-score-is-asked-to-do-three-incompatible-jobs" tabindex="-1">One Score Is Asked to Do Three Incompatible Jobs <a class="header-anchor" href="#one-score-is-asked-to-do-three-incompatible-jobs" aria-label="Permalink to &quot;One Score Is Asked to Do Three Incompatible Jobs&quot;">​</a></h2><p>A common router translates confidence below a threshold into “use more agents.” That move silently combines three questions:</p><ol><li>Does the current execution deserve escalation consideration?</li><li>Which available collaboration protocol is likely to add value for this task?</li><li>Is that expected increment worth the token, latency, compute, tool, or human-review budget?</li></ol><p>The decisions may share features, but they must not silently share authority. Risk evidence can open a selection process. Value evidence must bind a task, model, and named candidate protocol. Budget evidence answers whether the organization will pay for that expected increment.</p><h2 id="controlled-evidence-exposes-the-gap-between-risk-and-protocol-choice" tabindex="-1">Controlled Evidence Exposes the Gap Between Risk and Protocol Choice <a class="header-anchor" href="#controlled-evidence-exposes-the-gap-between-risk-and-protocol-choice" aria-label="Permalink to &quot;Controlled Evidence Exposes the Gap Between Risk and Protocol Choice&quot;">​</a></h2><p>The primary study captured by the same-date Research Object compares a baseline, a single-agent enhancement, planner–executor–reviewer collaboration, and broadcast collaboration over 4,181 competition-level mathematics problems. On 4,151 parseable examples, a post-answer probe discriminates baseline failure with reported AUROC 0.8847 and AUPRC 0.895.</p><p>Predicting whether a particular protocol adds value is much harder. The study reports AUPRC 0.1674 for PER-first value and 0.1041 for Broadcast-only value. Matched outcomes also show that the more expensive topology does not dominate every task, while token use differs materially across protocols.</p><p>These figures describe the study setting, not enterprise thresholds. The post-answer probe also uses information that exists only after an initial answer, so it cannot prove equivalent pre-execution performance. The supported conclusion is narrower: strong evidence that an answer is risky does not substitute for protocol-specific value evidence.</p><h2 id="three-evidence-receipts-make-one-escalation" tabindex="-1">Three Evidence Receipts Make One Escalation <a class="header-anchor" href="#three-evidence-receipts-make-one-escalation" aria-label="Permalink to &quot;Three Evidence Receipts Make One Escalation&quot;">​</a></h2><p>A governed transition can preserve three independent records:</p><table tabindex="0"><thead><tr><th>Decision</th><th>Minimum evidence</th><th>Authorized next step</th><th>What it does not prove</th></tr></thead><tbody><tr><td>Failure-risk admission</td><td>Current path, risk model, calibration scope, freshness</td><td>Enter escalation consideration</td><td>A named protocol will help</td></tr><tr><td>Protocol-value routing</td><td>Task, model, candidates, expected increment</td><td>Rank or select a candidate</td><td>The cost is authorized</td></tr><tr><td>Budget admission</td><td>Expected cost, limits, value threshold, approving owner</td><td>Execute a bounded choice</td><td>The protocol is generally optimal</td></tr></tbody></table><p>When protocol-value evidence is weak, a runtime should not translate high failure probability into the most expensive default. It can preserve an explicit “high risk, uncertain protocol” state and apply a governed fallback: a cheap critique, human review, problem decomposition, or a stop.</p><p>The decomposition also improves incident diagnosis. Failure to escalate can be a risk-estimation error. Escalating to the wrong topology is a value-ranking error. Selecting a useful topology that exceeds limits is a budget-governance error. Those failure classes require different repairs.</p><h2 id="one-model-may-decide-jointly-the-evidence-still-has-layers" tabindex="-1">One Model May Decide Jointly; The Evidence Still Has Layers <a class="header-anchor" href="#one-model-may-decide-jointly-the-evidence-still-has-layers" aria-label="Permalink to &quot;One Model May Decide Jointly; The Evidence Still Has Layers&quot;">​</a></h2><p>A practical system may use one learned policy to optimize quality and cost jointly. That is a reasonable implementation choice. It does not erase the semantic distinctions.</p><p>Even if one model emits the decision, the durable record should explain which observations supported risk, what increment was expected from each candidate, and which cost function, cap, and approving principal admitted execution. Without those facts, a policy change cannot be diagnosed as better calibration, better protocol ranking, or merely a looser budget.</p><p>A fixed expensive protocol may also be rational in a safety-critical or extremely high-value domain. The study does not rule out that policy. It requires the organization to record “always broadcast” as an explicit resource decision, not as a technical conclusion implied by uncertainty alone.</p><h2 id="from-a-binary-feature-to-an-auditable-execution-policy" tabindex="-1">From a Binary Feature to an Auditable Execution Policy <a class="header-anchor" href="#from-a-binary-feature-to-an-auditable-execution-policy" aria-label="Permalink to &quot;From a Binary Feature to an Auditable Execution Policy&quot;">​</a></h2><p>A team can begin with four changes:</p><ul><li>Store whether to consider escalation separately from where to escalate.</li><li>Bind protocol recommendations to the task distribution, model version, tool set, and candidate topology.</li><li>Define separate budgets for tokens, latency, parallel tool use, and human review.</li><li>Provide a deterministic fallback for uncertain protocol value and record why it stopped.</li></ul><p>Evaluation should likewise distinguish under-escalation, over-escalation, wrong-protocol selection, and budget overrun. “Multi-agent” then becomes an explainable execution-policy choice instead of an overloaded capability switch.</p><h2 id="evidence-boundary-and-open-questions" tabindex="-1">Evidence Boundary and Open Questions <a class="header-anchor" href="#evidence-boundary-and-open-questions" aria-label="Permalink to &quot;Evidence Boundary and Open Questions&quot;">​</a></h2><p>The evidence comes from competition mathematics, one main solver family, and limited breadth checks. It does not prove transfer to software engineering, operations, or enterprise work. Study token counts are not product prices, and matched outcomes are not a complete stochastic characterization of repeated generation.</p><p>Open questions include which production-time features predict protocol value without outcome leakage; whether structured failure classes outperform scalar confidence; how to price latency, parallelism, external tools, and human review; whether a materially broader collaboration scope needs a new authorization receipt; and when calibration should expire after changes to the model, task distribution, or protocol family.</p><p>Until those questions are answered, the strongest default is not “more risk means more agents.” It is to require separate evidence for why escalation should be considered, why this protocol was selected, and why this cost is authorized now.</p><p><strong>Evidence and source:</strong></p><ul><li><a href="https://arxiv.org/abs/2608.14927" target="_blank" rel="noreferrer">Cost-aware multi-agent routing primary study</a></li></ul>',30))])}const v=t(l,[["render",c]]);export{b as __pageData,v as default};
